use anyhow::Result;
use serde::{Serialize,Deserialize};

#[derive(Clone,Copy,Debug,Default,PartialEq,Eq,Serialize,Deserialize,clap::ValueEnum)]
#[serde(rename_all="kebab-case")]
pub enum Provider {#[default] Entra,Okta,Auth0,Google,Keycloak,SamlBridge,GenericOidc}
impl Provider {
    pub const ALL:[Self;7]=[Self::Entra,Self::Okta,Self::Auth0,Self::Google,Self::Keycloak,Self::SamlBridge,Self::GenericOidc];
    pub fn label(self)->&'static str {match self {Self::Entra=>"Microsoft Entra ID",Self::Okta=>"Okta",Self::Auth0=>"Auth0",Self::Google=>"Google Workspace",Self::Keycloak=>"Keycloak",Self::SamlBridge=>"SAML via Keycloak",Self::GenericOidc=>"Other OIDC provider"}}
}
pub fn generate(provider:Provider,broker:&str,tenant:&str,client_id:&str)->Result<String> {
    let broker=super::broker_url(broker)?;
    let tenant=tenant.trim();let tenant=if tenant.is_empty(){"REPLACE_WITH_TENANT_OR_DOMAIN"}else{tenant};
    let client=if client_id.trim().is_empty(){"REPLACE_WITH_APPLICATION_CLIENT_ID"}else{client_id.trim()};
    let callback=format!("{broker}/auth/callback");
    let (issuer,steps,source)=match provider {
        Provider::Entra=>(format!("https://login.microsoftonline.com/{tenant}/v2.0"),
            "1. In Microsoft Entra admin center, open App registrations → New registration. Name it **lttl key service**. Select **Accounts in this organizational directory only**.\n2. Add a **Web** platform with the exact redirect URI below. This is a confidential server application; do not register the broker as a SPA or native public client, and do not enable implicit grants.\n3. Copy the Directory (tenant) ID and Application (client) ID. Create a client secret under Certificates & secrets and store its **value** only in the key-service secret store. Plan secret rotation before expiration.\n4. Under Token configuration, add the optional **auth_time** ID-token claim. The service requires fresh authentication time and fails closed without it. No Microsoft Graph directory permission is needed for the enrolled-user picker.\n5. In Enterprise applications, require assignment and assign a pilot group. Apply Conditional Access to this application: required MFA/authentication strength and approved network/location rules. Test allowed and denied cases; a successful password sign-in alone does not prove the policy is configured.",
            "[App registration](https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app) · [OIDC](https://learn.microsoft.com/en-us/entra/identity-platform/v2-protocols-oidc) · [Optional claims](https://learn.microsoft.com/en-us/entra/identity-platform/optional-claims-reference) · [Conditional Access](https://learn.microsoft.com/en-us/entra/identity/conditional-access/overview)"),
        Provider::Okta=>(format!("https://{tenant}"),
            "1. In the Okta Admin Console, create an app integration with **OIDC - OpenID Connect** and **Web Application**. Enable Authorization Code.\n2. Set Sign-in redirect URI to the exact callback below. Restrict assignments to your intended users/groups.\n3. Copy the client ID and client secret. Configure the issuer shown by your Okta authorization server; the organization URL below is a starting point, not a substitute for checking discovery. Use client_secret_post for token endpoint authentication.\n4. Apply the app sign-on/authentication policy for MFA, device requirements and network zones. Confirm that max_age=0 produces a fresh auth_time claim. The application requests a fresh login for every archive-opening authorization.",
            "[Okta web redirect integration](https://developer.okta.com/docs/guides/sign-into-web-app-redirect/) · [Create OIDC integrations](https://help.okta.com/en-us/content/topics/apps/apps_app_integration_wizard_oidc.htm)"),
        Provider::Auth0=>(format!("https://{tenant}/"),
            "1. Create a **Regular Web Application**. Set Allowed Callback URLs to the exact callback below, with no wildcard.\n2. Enable Authorization Code and the required enterprise connection. Record the client ID, client secret and exact issuer (including its trailing slash). Use client_secret_post token endpoint authentication.\n3. Restrict the connection/organization to the company’s intended users. Configure MFA and tenant/connection access policies. Verify fresh auth_time in the code-flow ID token.\n4. If the company uses SAML upstream, configure the enterprise SAML connection in Auth0 and validate that each opening enforces upstream reauthentication and company policy.",
            "[Auth0 application settings](https://auth0.com/docs/get-started/applications/application-settings) · [Force reauthentication](https://auth0.com/docs/authenticate/login/max-age-reauthentication)"),
        Provider::Google=>("https://accounts.google.com".into(),
            "1. In Google Cloud, configure the OAuth consent screen for the company and create an OAuth client of type **Web application**. Add the exact callback below as an Authorized redirect URI.\n2. Copy the client ID and secret. For Workspace-only use, restrict the consent/application audience to the organization. A domain hint is not an authorization boundary.\n3. This preview requires a verified fresh auth_time claim for every opening. Test that requirement before use: a provider that omits auth_time or ignores max_age cannot meet this service’s policy contract and will be rejected.\n4. If direct Google OIDC does not meet the freshness requirement, use the company’s policy-capable federation broker instead. Google-specific behavior has not been tenant-validated here.",
            "[Google OIDC registration and claims](https://developers.google.com/identity/openid-connect/openid-connect)"),
        Provider::Keycloak|Provider::SamlBridge=>(format!("https://{tenant}/realms/REPLACE_REALM"),
            "1. In the company’s Keycloak realm, create an **OpenID Connect** client. Enable client authentication and Standard Flow (Authorization Code); disable implicit and direct-access grants.\n2. Set Valid redirect URIs to the exact callback below, without wildcards. Use the realm’s exact issuer and client secret, and require S256 PKCE.\n3. For an existing SAML IDP, create a **SAML v2.0 identity provider** in Keycloak. Import the company IDP metadata and require signed assertions/responses with trusted signing certificates, audience and destination validation. Obtain Keycloak’s generated SP entity ID/ACS metadata and register that enterprise application in Entra, Okta, AD FS, Ping or the other SAML IDP.\n4. Enable upstream Force Authentication and configure MFA/location policy for the SAML application. Use a persistent immutable account identifier; do not automatically link accounts by unverified email. Verify that a fresh downstream auth_time represents a fresh upstream policy check.\n5. The lttl service consumes OIDC from Keycloak. It does not parse SAML assertions itself.",
            "[Keycloak identity brokering](https://www.keycloak.org/docs/latest/server_admin/index.html#_identity_broker)"),
        Provider::GenericOidc=>(format!("https://{tenant}"),
            "1. Create a confidential **Web** OIDC application with Authorization Code and S256 PKCE. Register the exact callback below. OAuth-only providers without OIDC ID tokens are insufficient.\n2. Supply the exact issuer with discovery and JWKS, client ID and secret. Configure client_secret_post authentication. Tokens must validate issuer, audience, signature, expiry, nonce and fresh auth_time under max_age=0.\n3. Assign the company’s intended users and configure app-specific MFA/location policy. Test policy denial as well as success. Where available, set required_acr in the broker to the exact authentication-context value your IDP contract guarantees.\n4. For SAML-only providers use the SAML federation setup, not a token-validation bypass.",
            "[OpenID Connect Core](https://openid.net/specs/openid-connect-core-1_0.html)"),
    };
    let config=serde_json::json!({"public_url":broker,"issuer":issuer,"client_id":client});
    let profile=serde_json::json!({"broker_url":broker,"provider":provider});
    Ok(format!("# lttl registration — {}\n\nThese instructions create an application in the company’s existing IDP. The lttl key service is a separate, company-hosted key-release API, not another IDP. Registration is performed by the tenant administrator; this guide does not create it automatically.\n\n## Registration values\n\n- Application: lttl key service\n- Type: confidential Web application\n- Flow: Authorization Code with S256 PKCE\n- Redirect / callback URI: `{callback}`\n- Scopes: `openid profile email`\n- No wildcard redirect URIs, implicit flow, password grant, refresh token or desktop client secret.\n\n## Provider steps\n\n{steps}\n\n{source}\n\n## Key service configuration\n\nCopy these IDP fields into the chosen hosting example in `identity-broker/deploy/serverless/`, then add its native KMS key reference. The hosting guide below supplies database and function settings.\n\n```json\n{}\n```\n\nThe key service runs on Azure Functions, AWS Lambda or Google Cloud Run with shared PostgreSQL state. Inject `LTTL_OIDC_CLIENT_SECRET` and `LTTL_DATABASE_URL` through protected platform settings. Native KMS wraps archive keys without exporting the cloud master key. Do not set `LTTL_BROKER_MASTER_KEY` for these deployments. No VM or cloud CLI is required at runtime. See the hosting instructions below and `identity-broker/deploy/test-environment.md`. Build the broker with Rust 1.92 or newer; initialize the PostgreSQL schema before deployment. Restrict logs so they do not capture authorization headers, response keys or callback query strings.\n\n## Desktop profile\n\nSave this JSON, or enter the service URL in lttl → Identity & sharing.\n\n```json\n{}\n```\n\n## Enroll and share\n\nEach recipient signs in once to enroll with this key service. Refresh the recipient picker, select the intended accounts, and create a `.lttl` protected archive. Names/email are display labels only; authorization uses the verified issuer and subject. The creator is not automatically added as a recipient. To open/list/test/extract, the recipient must sign in again and be in the archive’s allowlist. The key service must be reachable.\n\nThe sender already has the source data, and an authorized recipient can retain decrypted data or keys. This is access-controlled encryption, not DRM or revocation of copies already obtained. The key-service operator can access stored keys. Keep its database and cloud key versions recoverable; losing either can make archives permanently unreadable. The preview uses temporary plaintext archive files during compression/decryption and cleans them on normal completion/errors, but cannot guarantee erasure after a crash or from storage snapshots. Use an encrypted, access-restricted temporary volume.\n\n## Acceptance checks\n\nValidate recipient success, nonrecipient denial, two accounts with the same display email remaining distinct, disabled-user/policy denial, fresh MFA/location enforcement, wrong tenant, service outage, revocation, tampered archive, and a second opening requiring fresh sign-in. Changing the IDP app client ID or issuer can change subject identifiers and break existing access; plan identity migrations explicitly.\n",provider.label(),serde_json::to_string_pretty(&config)?,serde_json::to_string_pretty(&profile)?))
}
